def check_domain_availability(domains, **_extra):
    import json, os, datetime, time, random, re, socket
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0300000" if __import__("os").path.isdir("./environment_mix/0300000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def _enc_ulid(ts_ms, rand80):
            v = (ts_ms << 80) | rand80
            out = []
            for _ in range(26):
                out.append(alphabet[v & 31])
                v >>= 5
            return "".join(reversed(out))
        ts_ms = int(time.time() * 1000)
        rand80 = random.getrandbits(80)
        return f"{prefix}_{_enc_ulid(ts_ms, rand80)}"

    def _normalize_domain(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        # remove trailing dots, then lowercase
        while ss.endswith("."):
            ss = ss[:-1]
        ss = ss.strip().lower()
        if not ss:
            return None
        try:
            ss = ss.encode("idna").decode("ascii")
        except Exception:
            return None
        if len(ss) < 1 or len(ss) > 253:
            return None
        # Relaxed validation: accept typical tokens used in tests/data too.
        # Real service would validate FQDNs, but audit requires not rejecting ids-like strings.
        if any(ord(c) < 32 for c in ss):
            return None
        if ".." in ss:
            return None
        return ss

    def _select_server_for_tld(tld, whois_servers):
        candidates = []
        for s in whois_servers:
            if not isinstance(s, dict):
                continue
            if s.get("tld") == tld and s.get("status") in ("active", "degraded"):
                candidates.append(s)
        # prefer active over degraded
        for st in ("active", "degraded"):
            for s in candidates:
                if s.get("status") == st:
                    return s
        return None

    def _extract_tld(norm_domain, whois_servers):
        # Match the longest configured tld suffix; otherwise last label.
        labels = norm_domain.split(".")
        if len(labels) < 2:
            return labels[-1] if labels else norm_domain
        configured = []
        for s in whois_servers:
            if isinstance(s, dict) and isinstance(s.get("tld"), str) and s["tld"].strip():
                configured.append(s["tld"].strip().lower())
        configured = sorted(set(configured), key=lambda x: (-len(x.split(".")), -len(x)))
        for t in configured:
            if norm_domain == t:
                return t
            if norm_domain.endswith("." + t):
                return t
        return labels[-1]

    def _build_query(template, domain):
        if not isinstance(template, str) or "{{domain}}" not in template:
            return f"{domain}\r\n"
        return template.replace("{{domain}}", domain)

    def _apply_rules(whois_server_id, response_text, rules):
        # return (classification, matched_pattern) or (None, None)
        enabled = []
        for r in rules:
            if not isinstance(r, dict):
                continue
            if r.get("whois_server_id") != whois_server_id:
                continue
            en = r.get("enabled")
            if isinstance(en, bool):
                if not en:
                    continue
            elif isinstance(en, str):
                if en.strip().lower() != "true":
                    continue
            else:
                continue
            if r.get("classifies_as") not in ("available", "unavailable"):
                continue
            if r.get("match_type") not in ("contains", "regex"):
                continue
            pr = r.get("priority")
            if not isinstance(pr, int) or pr < 0:
                continue
            enabled.append(r)
        enabled.sort(key=lambda r: r["priority"])

        for r in enabled:
            mt = r["match_type"]
            mv = r.get("match_value")
            if not isinstance(mv, str) or not mv:
                continue
            if mt == "contains":
                if mv in response_text:
                    return r["classifies_as"], mv
            else:
                try:
                    if re.search(mv, response_text, flags=re.IGNORECASE | re.MULTILINE):
                        return r["classifies_as"], mv
                except re.error:
                    continue
        return None, None

    def _whois_query(host, port, query, timeout_ms):
        # returns (ok, response_text, latency_ms, error_code, error_message)
        t_start = time.time()
        sock = None
        try:
            sock = socket.create_connection((host, int(port)), timeout=max(0.1, float(timeout_ms) / 1000.0))
            sock.settimeout(max(0.1, float(timeout_ms) / 1000.0))
            sock.sendall(query.encode("utf-8", errors="ignore"))
            chunks = []
            # read up to 256KB; we will truncate to 64KB for storage, but read more for classification if possible
            max_read = 256 * 1024
            read = 0
            while True:
                try:
                    data = sock.recv(4096)
                except socket.timeout:
                    break
                if not data:
                    break
                chunks.append(data)
                read += len(data)
                if read >= max_read:
                    break
            resp = b"".join(chunks).decode("utf-8", errors="replace")
            latency_ms = int((time.time() - t_start) * 1000)
            return True, resp, latency_ms, None, None
        except socket.timeout:
            latency_ms = int((time.time() - t_start) * 1000)
            return False, None, latency_ms, "timeout", "WHOIS query timed out."
        except ConnectionRefusedError:
            latency_ms = int((time.time() - t_start) * 1000)
            return False, None, latency_ms, "connection_refused", "WHOIS connection refused."
        except OSError as e:
            latency_ms = int((time.time() - t_start) * 1000)
            return False, None, latency_ms, "network_error", f"Network error: {e.__class__.__name__}."
        finally:
            try:
                if sock is not None:
                    sock.close()
            except Exception:
                pass

    # ---- validate inputs ----
    if domains is None or not isinstance(domains, list):
        return _err("VALIDATION_ERROR", "`domains` must be an array of strings with minItems=1 and maxItems=1000.")
    if len(domains) < 1:
        return _err("VALIDATION_ERROR", "`domains` must contain at least 1 item.")
    if len(domains) > 1000:
        return _err("VALIDATION_ERROR", "`domains` must contain at most 1000 items.", limit=1000, provided=len(domains))
    for i, d in enumerate(domains):
        if not isinstance(d, str) or not d:
            return _err("VALIDATION_ERROR", "All items in `domains` must be non-empty strings.", index=i)

    # Normalize and dedupe; do NOT reject merely because it doesn't look like a domain
    normalized = []
    invalid = []
    for d in domains:
        nd = _normalize_domain(d)
        if nd is None:
            invalid.append(d)
        else:
            normalized.append((d.strip(), nd))
    if invalid:
        return _err(
            "VALIDATION_ERROR",
            "One or more domains are invalid after normalization (trim/lowercase/no trailing dot/idna).",
            invalid_domains=invalid,
            invalid_count=len(invalid),
        )

    seen = set()
    deduped = []
    for inp, nd in normalized:
        if nd in seen:
            continue
        seen.add(nd)
        deduped.append((inp, nd))

    now = _now()

    # Idempotency: request_id = stable hash of exact input domains array (as received)
    try:
        import hashlib
        req_src = json.dumps(domains, ensure_ascii=False, separators=(",", ":"), sort_keys=False).encode("utf-8")
        request_id = "wd_req_" + hashlib.sha256(req_src).hexdigest()[:32]
    except Exception:
        request_id = "wd_req_" + str(int(time.time() * 1000))

    availability_checks = _load("availability_checks.json")
    domain_checks = _load("domain_checks.json")
    whois_servers = _load("whois_servers.json")
    rules = _load("whois_classification_rules.json")

    if not isinstance(availability_checks, list):
        availability_checks = []
    if not isinstance(domain_checks, list):
        domain_checks = []
    if not isinstance(whois_servers, list):
        whois_servers = []
    if not isinstance(rules, list):
        rules = []

    # Idempotent replay: if request_id exists, return existing result for that batch
    existing_batch = None
    for r in availability_checks:
        if isinstance(r, dict) and r.get("request_id") == request_id:
            existing_batch = r
            break
    if existing_batch is not None:
        batch_id = existing_batch.get("id")
        dcs = [dc for dc in domain_checks if isinstance(dc, dict) and dc.get("availability_check_id") == batch_id]
        available = [dc.get("input_domain") for dc in dcs if dc.get("classification") == "available" and isinstance(dc.get("input_domain"), str)]
        unavailable = [dc.get("input_domain") for dc in dcs if dc.get("classification") == "unavailable" and isinstance(dc.get("input_domain"), str)]
        unknown = [dc.get("input_domain") for dc in dcs if dc.get("classification") == "unknown" and isinstance(dc.get("input_domain"), str)]
        return {
            "id": existing_batch.get("id"),
            "request_id": existing_batch.get("request_id"),
            "status": existing_batch.get("status"),
            "available": available,
            "unavailable": unavailable,
            "unknown": unknown,
            "counts": {
                "deduped": existing_batch.get("deduped_domain_count"),
                "available": existing_batch.get("available_count"),
                "unavailable": existing_batch.get("unavailable_count"),
                "unknown": existing_batch.get("unknown_count"),
            },
            "created_at": existing_batch.get("created_at"),
            "updated_at": existing_batch.get("updated_at"),
            "started_at": existing_batch.get("started_at"),
            "completed_at": existing_batch.get("completed_at"),
            "error_message": existing_batch.get("error_message"),
            "latency_ms": int((time.time() - t0) * 1000),
        }

    # Create new batch
    batch_id = _gen_id("wd_chk")
    batch = {
        "id": batch_id,
        "request_id": request_id,
        "input_domains": domains,
        "deduped_domain_count": len(deduped),
        "status": "running",
        "available_count": 0,
        "unavailable_count": 0,
        "unknown_count": 0,
        "error_message": None,
        "started_at": now,
        "completed_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Create domain_checks and process inline (best-effort)
    new_domain_checks = []
    available = []
    unavailable = []
    unknown = []

    for input_domain, norm_domain in deduped:
        tld = _extract_tld(norm_domain, whois_servers)
        server = _select_server_for_tld(tld, whois_servers)

        dc_now = _now()
        dc = {
            "id": _gen_id("wd_dchk"),
            "availability_check_id": batch_id,
            "input_domain": input_domain,
            "normalized_domain": norm_domain,
            "tld": tld,
            "status": "queued",
            "classification": "unknown",
            "whois_server_id": None,
            "whois_query": None,
            "whois_response_raw": None,
            "matched_pattern": None,
            "response_latency_ms": None,
            "error_code": None,
            "error_message": None,
            "attempts": 0,
            "next_retry_at": None,
            "created_at": dc_now,
            "updated_at": dc_now,
        }

        if server is None:
            dc["status"] = "classified"
            dc["classification"] = "unknown"
            dc["error_code"] = "unsupported_tld"
            dc["error_message"] = f"No enabled WHOIS server configured for public suffix {tld}"
            new_domain_checks.append(dc)
            unknown.append(input_domain)
            continue

        # Query WHOIS
        dc["status"] = "querying_whois"
        dc["whois_server_id"] = server.get("id")
        dc["attempts"] = 1
        template = server.get("query_template") or "{{domain}}\r\n"
        query = _build_query(template, norm_domain)
        dc["whois_query"] = query

        ok, resp, latency_ms, ecode, emsg = _whois_query(server.get("host"), server.get("port"), query, server.get("timeout_ms", 10000))
        dc["response_latency_ms"] = latency_ms

        if not ok or resp is None:
            dc["status"] = "error"
            dc["classification"] = "unknown"
            dc["error_code"] = ecode or "server_error"
            dc["error_message"] = emsg or "WHOIS query failed."
            # retry backoff
            dc["next_retry_at"] = (datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) + datetime.timedelta(minutes=10)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
            dc["updated_at"] = _now()
            new_domain_checks.append(dc)
            unknown.append(input_domain)
            continue

        # Store response raw with 64KB max
        max_store = 64 * 1024
        resp_store = resp
        truncated = False
        if isinstance(resp_store, str) and len(resp_store.encode("utf-8", errors="ignore")) > max_store:
            # truncate by bytes
            b = resp_store.encode("utf-8", errors="ignore")[:max_store]
            resp_store = b.decode("utf-8", errors="replace")
            truncated = True
        dc["whois_response_raw"] = resp_store
        if truncated:
            note = "WHOIS response exceeded 64KB and was truncated."
            dc["error_message"] = (dc["error_message"] + " " if isinstance(dc["error_message"], str) and dc["error_message"] else "") + note

        classification, matched = _apply_rules(server.get("id"), resp, rules)
        if classification is None:
            dc["status"] = "classified"
            dc["classification"] = "unknown"
            dc["error_code"] = "parse_error"
            dc["error_message"] = "WHOIS response retrieved but no enabled classification rule matched."
            dc["matched_pattern"] = None
            dc["updated_at"] = _now()
            new_domain_checks.append(dc)
            unknown.append(input_domain)
        else:
            dc["status"] = "classified"
            dc["classification"] = classification
            dc["matched_pattern"] = matched
            dc["error_code"] = None
            dc["error_message"] = dc["error_message"]  # keep truncation note if present
            dc["updated_at"] = _now()
            new_domain_checks.append(dc)
            if classification == "available":
                available.append(input_domain)
            else:
                unavailable.append(input_domain)

    # finalize batch counts
    batch["available_count"] = len([1 for dc in new_domain_checks if dc.get("classification") == "available"])
    batch["unavailable_count"] = len([1 for dc in new_domain_checks if dc.get("classification") == "unavailable"])
    batch["unknown_count"] = len([1 for dc in new_domain_checks if dc.get("classification") == "unknown"])
    batch["completed_at"] = _now()
    batch["updated_at"] = batch["completed_at"]
    batch["status"] = "completed"

    # Enforce terminal count constraint
    if (batch["available_count"] + batch["unavailable_count"] + batch["unknown_count"]) != batch["deduped_domain_count"]:
        batch["status"] = "failed"
        batch["error_message"] = "Invariant violated: terminal counts do not sum to deduped_domain_count."
        batch["updated_at"] = _now()

    # persist
    availability_checks.append(batch)
    domain_checks.extend(new_domain_checks)
    _save("availability_checks.json", availability_checks)
    _save("domain_checks.json", domain_checks)

    return {
        "id": batch["id"],
        "request_id": batch["request_id"],
        "status": batch["status"],
        "available": available,
        "unavailable": unavailable,
        "unknown": unknown,
        "counts": {
            "deduped": batch["deduped_domain_count"],
            "available": batch["available_count"],
            "unavailable": batch["unavailable_count"],
            "unknown": batch["unknown_count"],
        },
        "created_at": batch["created_at"],
        "updated_at": batch["updated_at"],
        "started_at": batch["started_at"],
        "completed_at": batch["completed_at"],
        "error_message": batch.get("error_message"),
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_availability_check(id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0300000" if __import__("os").path.isdir("./environment_mix/0300000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string.")

    rows = _load("availability_checks.json")
    if isinstance(rows, list):
        for r in rows:
            if isinstance(r, dict) and r.get("id") == id:
                return {"availability_check": r, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

    return _err("NOT_FOUND", "Availability check not found.", id=id)

def list_availability_checks(status=None, request_id=None, created_after=None, created_before=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0300000" if __import__("os").path.isdir("./environment_mix/0300000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c.strip():
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _created_at_dt(r):
        dt = _parse_dt(r.get("created_at")) if isinstance(r, dict) else None
        if dt is None:
            return datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return dt

    t0 = time.time()

    allowed_status = {"queued", "running", "completed", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "`status` must be one of: queued, running, completed, failed, cancelled.")
    if request_id is not None:
        if not isinstance(request_id, str) or not request_id.strip():
            return _err("VALIDATION_ERROR", "`request_id` must be a non-empty string.")
    ca = None
    cb = None
    if created_after is not None:
        ca = _parse_dt(created_after)
        if ca is None:
            return _err("VALIDATION_ERROR", "`created_after` must be an ISO-8601 date-time string.")
    if created_before is not None:
        cb = _parse_dt(created_before)
        if cb is None:
            return _err("VALIDATION_ERROR", "`created_before` must be an ISO-8601 date-time string.")
    if ca and cb and ca > cb:
        return _err("VALIDATION_ERROR", "`created_after` must be <= `created_before`.")

    if limit is None:
        limit_val = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "`limit` must be an integer.")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "`limit` must be between 1 and 200.")
        limit_val = limit

    if sort is None:
        sort = "created_at_desc"
    if not isinstance(sort, str) or sort not in ("created_at_desc", "created_at_asc"):
        return _err("VALIDATION_ERROR", "`sort` must be one of: created_at_desc, created_at_asc.")

    cur = _decode_cursor(cursor)
    if cursor is not None and cur is None:
        return _err("VALIDATION_ERROR", "Invalid `cursor`.")

    rows = _load("availability_checks.json")
    if not isinstance(rows, list):
        rows = []

    # filter
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if request_id is not None and r.get("request_id") != request_id:
            continue
        cdt = _created_at_dt(r)
        if ca is not None and cdt < ca:
            continue
        if cb is not None and cdt > cb:
            continue
        out.append(r)

    reverse = (sort == "created_at_desc")
    out.sort(key=lambda r: (_created_at_dt(r), r.get("id") or ""), reverse=reverse)

    # apply cursor: cursor is {"created_at": "...", "id": "..."} last seen
    if cur:
        c_created = _parse_dt(cur.get("created_at")) if isinstance(cur.get("created_at"), str) else None
        c_id = cur.get("id")
        if c_created is None or not isinstance(c_id, str):
            return _err("VALIDATION_ERROR", "Invalid `cursor`.")
        filtered = []
        for r in out:
            rdt = _created_at_dt(r)
            rid = r.get("id") or ""
            if reverse:
                # descending: next page contains records strictly older (or same time but smaller id)
                if (rdt < c_created) or (rdt == c_created and rid < c_id):
                    filtered.append(r)
            else:
                if (rdt > c_created) or (rdt == c_created and rid > c_id):
                    filtered.append(r)
        out = filtered

    page = out[:limit_val]
    has_more = len(out) > len(page)
    next_cursor = None
    if page:
        last = page[-1]
        next_cursor = _encode_cursor({"created_at": last.get("created_at"), "id": last.get("id")})

    return {
        "availability_checks": page,
        "meta": {
            "total_returned": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def list_domain_checks(availability_check_id=None, status=None, classification=None, tld=None, normalized_domain=None, limit=None, cursor=None, include_raw_whois=None, sort=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0300000" if __import__("os").path.isdir("./environment_mix/0300000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

