            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c.strip():
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _created_at_dt(r):
        dt = _parse_dt(r.get("created_at")) if isinstance(r, dict) else None
        if dt is None:
            return datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return dt

    t0 = time.time()

    if include_raw_whois is None:
        include_raw_whois = False
    if not isinstance(include_raw_whois, bool):
        return _err("VALIDATION_ERROR", "`include_raw_whois` must be a boolean.")

    if availability_check_id is not None and (not isinstance(availability_check_id, str) or not availability_check_id.strip()):
        return _err("VALIDATION_ERROR", "`availability_check_id` must be a non-empty string.")
    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "querying_whois", "classified", "error"):
            return _err("VALIDATION_ERROR", "`status` must be one of: queued, querying_whois, classified, error.")
    if classification is not None:
        if not isinstance(classification, str) or classification not in ("available", "unavailable", "unknown"):
            return _err("VALIDATION_ERROR", "`classification` must be one of: available, unavailable, unknown.")
    if tld is not None and (not isinstance(tld, str) or not tld.strip()):
        return _err("VALIDATION_ERROR", "`tld` must be a non-empty string.")
    if normalized_domain is not None and (not isinstance(normalized_domain, str) or not normalized_domain.strip()):
        return _err("VALIDATION_ERROR", "`normalized_domain` must be a non-empty string.")

    if limit is None:
        limit_val = 100
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "`limit` must be an integer.")
        if limit < 1 or limit > 500:
            return _err("VALIDATION_ERROR", "`limit` must be between 1 and 500.")
        limit_val = limit

    if sort is None:
        sort = "created_at_desc"
    if not isinstance(sort, str) or sort not in ("created_at_desc", "created_at_asc"):
        return _err("VALIDATION_ERROR", "`sort` must be one of: created_at_desc, created_at_asc.")

    cur = _decode_cursor(cursor)
    if cursor is not None and cur is None:
        return _err("VALIDATION_ERROR", "Invalid `cursor`.")

    rows = _load("domain_checks.json")
    if not isinstance(rows, list):
        rows = []

    out = []
    tld_norm = tld.strip().lower() if isinstance(tld, str) else None
    nd_norm = normalized_domain.strip().lower() if isinstance(normalized_domain, str) else None

    for r in rows:
        if not isinstance(r, dict):
            continue
        if availability_check_id is not None and r.get("availability_check_id") != availability_check_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if classification is not None and r.get("classification") != classification:
            continue
        if tld_norm is not None and (r.get("tld") or "").strip().lower() != tld_norm:
            continue
        if nd_norm is not None and (r.get("normalized_domain") or "").strip().lower() != nd_norm:
            continue

        rr = dict(r)
        if not include_raw_whois:
            rr.pop("whois_response_raw", None)
        out.append(rr)

    reverse = (sort == "created_at_desc")
    out.sort(key=lambda r: (_created_at_dt(r), r.get("id") or ""), reverse=reverse)

    if cur:
        c_created = _parse_dt(cur.get("created_at")) if isinstance(cur.get("created_at"), str) else None
        c_id = cur.get("id")
        if c_created is None or not isinstance(c_id, str):
            return _err("VALIDATION_ERROR", "Invalid `cursor`.")
        filtered = []
        for r in out:
            rdt = _created_at_dt(r)
            rid = r.get("id") or ""
            if reverse:
                if (rdt < c_created) or (rdt == c_created and rid < c_id):
                    filtered.append(r)
            else:
                if (rdt > c_created) or (rdt == c_created and rid > c_id):
                    filtered.append(r)
        out = filtered

    page = out[:limit_val]
    has_more = len(out) > len(page)
    next_cursor = None
    if page:
        last = page[-1]
        next_cursor = _encode_cursor({"created_at": last.get("created_at"), "id": last.get("id")})

    return {
        "domain_checks": page,
        "meta": {
            "total_returned": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def cancel_availability_check(id, reason=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0300000" if __import__("os").path.isdir("./environment_mix/0300000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if id is None or not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string.")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "`reason` must be a string when provided.")
        if not reason.strip():
            reason = None
        elif len(reason) > 500:
            return _err("VALIDATION_ERROR", "`reason` must be at most 500 characters.")

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    availability_checks = _load("availability_checks.json")
    domain_checks = _load("domain_checks.json")
    if not isinstance(availability_checks, list):
        availability_checks = []
    if not isinstance(domain_checks, list):
        domain_checks = []

    idx = None
    batch = None
    for i, r in enumerate(availability_checks):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            batch = r
            break
    if batch is None:
        return _err("NOT_FOUND", "Availability check not found.", id=id)

    cur_status = batch.get("status")
    if cur_status not in ("queued", "running"):
        return _err(
            "CONFLICT",
            "Cannot cancel availability check: only checks in `queued` or `running` may be cancelled (business rule: availability_checks.status transition queued|running -> cancelled only).",
            rule="availability_checks.lifecycle.transitions",
            status=cur_status,
        )

    now = _now()

    # Update batch
    new_batch = dict(batch)
    new_batch["status"] = "cancelled"
    if reason is not None:
        new_batch["error_message"] = reason
    new_batch["completed_at"] = now
    new_batch["updated_at"] = now

    # Update child domain_checks: set any non-terminal to error/unknown (best effort)
    # domain_checks lifecycle allows: queued -> error, querying_whois -> error
    affected = 0
    for j, dc in enumerate(domain_checks):
        if not isinstance(dc, dict):
            continue
        if dc.get("availability_check_id") != id:
            continue
        st = dc.get("status")
        if st in ("queued", "querying_whois"):
            ndc = dict(dc)
            ndc["status"] = "error"
            ndc["classification"] = "unknown"
            ndc["error_code"] = ndc.get("error_code") or "server_error"
            ndc["error_message"] = ndc.get("error_message") or ("Cancelled by user." if reason is None else f"Cancelled by user: {reason}")
            ndc["next_retry_at"] = None
            ndc["updated_at"] = now
            domain_checks[j] = ndc
            affected += 1

    # Recompute batch counters from all domain_checks for this batch
    dcs = [dc for dc in domain_checks if isinstance(dc, dict) and dc.get("availability_check_id") == id]
    new_batch["available_count"] = sum(1 for dc in dcs if dc.get("classification") == "available")
    new_batch["unavailable_count"] = sum(1 for dc in dcs if dc.get("classification") == "unavailable")
    new_batch["unknown_count"] = sum(1 for dc in dcs if dc.get("classification") == "unknown")
    # keep deduped_domain_count unchanged; it refers to unique normalized domains created at submission

    availability_checks[idx] = new_batch
    _save("availability_checks.json", availability_checks)
    _save("domain_checks.json", domain_checks)

    return {
        "id": new_batch["id"],
        "status": new_batch["status"],
        "reason": reason,
        "counts": {
            "deduped": new_batch.get("deduped_domain_count"),
            "available": new_batch.get("available_count"),
            "unavailable": new_batch.get("unavailable_count"),
            "unknown": new_batch.get("unknown_count"),
        },
        "updated_domain_checks": affected,
        "completed_at": new_batch.get("completed_at"),
        "updated_at": new_batch.get("updated_at"),
        "latency_ms": int((time.time() - t0) * 1000),
    }

def upsert_whois_server(tld, host, query_template, id=None, port=None, timeout_ms=None, max_requests_per_minute=None, status=None, notes=None, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0300000" if __import__("os").path.isdir("./environment_mix/0300000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        ts = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"{prefix}_{ts:013x}{rnd:020x}"

    if not isinstance(tld, str) or not tld.strip():
        return _err("VALIDATION_ERROR", "`tld` must be a non-empty string.")
    if not isinstance(host, str) or not host.strip():
        return _err("VALIDATION_ERROR", "`host` must be a non-empty string.")
    if not isinstance(query_template, str) or not query_template.strip():
        return _err("VALIDATION_ERROR", "`query_template` must be a non-empty string.")

    tld_norm = tld.strip().lower()
    host_norm = host.strip()
    qt_norm = query_template

    if id is not None and (not isinstance(id, str) or not id.strip()):
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string when provided.")

    if port is None:
        port_val = 43
    else:
        if not isinstance(port, int):
            return _err("VALIDATION_ERROR", "`port` must be an integer.")
        if port < 1 or port > 65535:
            return _err("VALIDATION_ERROR", "`port` must be between 1 and 65535.")
        port_val = port

    if timeout_ms is None:
        timeout_val = 5000
    else:
        if not isinstance(timeout_ms, int):
            return _err("VALIDATION_ERROR", "`timeout_ms` must be an integer.")
        if timeout_ms < 100 or timeout_ms > 60000:
            return _err("VALIDATION_ERROR", "`timeout_ms` must be between 100 and 60000.")
        timeout_val = timeout_ms

    # schema says max_requests_per_minute between 1 and 10000; tool schema allows up to 100000
    if max_requests_per_minute is None:
        mrm_val = 60
    else:
        if not isinstance(max_requests_per_minute, int):
            return _err("VALIDATION_ERROR", "`max_requests_per_minute` must be an integer.")
        if max_requests_per_minute < 1:
            return _err("VALIDATION_ERROR", "`max_requests_per_minute` must be >= 1.")
        mrm_val = max_requests_per_minute
        if mrm_val > 10000:
            return _err("VALIDATION_ERROR", "`max_requests_per_minute` must be <= 10000 (server constraint).")

    if status is None:
        status_val = "active"
    else:
        if not isinstance(status, str) or status not in ("active", "degraded", "disabled"):
            return _err("VALIDATION_ERROR", "`status` must be one of: active, degraded, disabled.")
        status_val = status

    if notes is not None:
        if not isinstance(notes, str):
            return _err("VALIDATION_ERROR", "`notes` must be a string when provided.")
        if len(notes) > 2000:
            return _err("VALIDATION_ERROR", "`notes` must be at most 2000 characters.")
        notes_val = notes
    else:
        notes_val = None

    servers = _load("whois_servers.json")
    if not isinstance(servers, list):
        servers = []

    # uniqueness on tld
    existing_for_tld = None
    for s in servers:
        if isinstance(s, dict) and (s.get("tld") or "").strip().lower() == tld_norm:
            existing_for_tld = s
            break

    now = _now()

    if id is not None:
        # update by id if present, else create-but-respect tld uniqueness
        idx = None
        existing = None
        for i, s in enumerate(servers):
            if isinstance(s, dict) and s.get("id") == id:
                idx = i
                existing = s
                break

        if existing is None:
            # Realistic behavior: if id not found but tld exists, update that row if it matches the target tld.
            # This relaxes callers that accidentally pass a non-server id.
            if existing_for_tld is not None:
                # update existing_for_tld (by its actual index)
                for i, s in enumerate(servers):
                    if s is existing_for_tld:
                        idx = i
                        existing = existing_for_tld
                        break
            else:
                # create new with provided id
                if existing_for_tld is not None:
                    return _err("CONFLICT", "TLD is already configured for a different WHOIS server.", tld=tld_norm, existing_id=existing_for_tld.get("id"))
                new_row = {
                    "id": id.strip(),
                    "tld": tld_norm,
                    "host": host_norm,
                    "port": int(port_val),
                    "query_template": qt_norm,
                    "timeout_ms": int(timeout_val),
                    "max_requests_per_minute": int(mrm_val),
                    "status": status_val,
                    "last_healthcheck_at": None,
                    "last_error_at": None,
                    "notes": notes_val,
                    "created_at": now,
                    "updated_at": now,
                }
                servers.append(new_row)
                _save("whois_servers.json", servers)
                return {"whois_server": new_row}
        # if updating existing but tld is changing to one owned by someone else -> conflict
        if existing_for_tld is not None and existing_for_tld.get("id") != existing.get("id") and tld_norm == (existing_for_tld.get("tld") or "").strip().lower():
            return _err("CONFLICT", "TLD is already configured for a different WHOIS server.", tld=tld_norm, existing_id=existing_for_tld.get("id"))

        new_row = dict(existing)
        new_row["tld"] = tld_norm
        new_row["host"] = host_norm
        new_row["port"] = int(port_val)
        new_row["query_template"] = qt_norm
        new_row["timeout_ms"] = int(timeout_val)
        new_row["max_requests_per_minute"] = int(mrm_val)
        new_row["status"] = status_val
        new_row["notes"] = notes_val
        new_row["updated_at"] = now
        servers[idx] = new_row
        _save("whois_servers.json", servers)
        return {"whois_server": new_row}

    # create (id omitted)
    if existing_for_tld is not None:
        return _err("CONFLICT", "TLD is already configured for a different WHOIS server.", tld=tld_norm, existing_id=existing_for_tld.get("id"))

    new_id = _gen_id("wd_who")
    new_row = {
        "id": new_id,
        "tld": tld_norm,
        "host": host_norm,
        "port": int(port_val),
        "query_template": qt_norm,
        "timeout_ms": int(timeout_val),
        "max_requests_per_minute": int(mrm_val),
        "status": status_val,
        "last_healthcheck_at": None,
        "last_error_at": None,
        "notes": notes_val,
        "created_at": now,
        "updated_at": now,
    }
    servers.append(new_row)
    _save("whois_servers.json", servers)
    return {"whois_server": new_row}

def get_auth_context(include_rate_limits=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0300000" if __import__("os").path.isdir("./environment_mix/0300000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if include_rate_limits is None:
        include_rate_limits = True
    if not isinstance(include_rate_limits, bool):
        return _err("VALIDATION_ERROR", "`include_rate_limits` must be a boolean.")

    ctx = {
        "authenticated": True,
        "subject": {"type": "ambient", "id": "caller"},
        "scopes": ["domain:read", "domain:check", "whois:admin"],
    }

    if include_rate_limits:
        # No explicit usage/audit collections exist in provided schema; return best-effort note.
        ctx["rate_limits"] = {
            "enforced": False,
            "note": "Rate limits/quotas are not enforced because no usage/audit datastore collection is defined for this service snapshot.",
        }

    return {"auth_context": ctx}
